export const YEAR_RANGES = [
  { label: "All Years", value: "all" },
  { label: "2023-2025", value: "2023-2025" },
  { label: "2020-2022", value: "2020-2022" },
  { label: "Before 2020", value: "before-2020" },
];

export function searchCuratedPapers(query: string, papers: CuratedPaper[]): CuratedPaper[] {
  const q = query.toLowerCase();
  return papers.filter(p =>
    p.title.toLowerCase().includes(q) ||
    p.abstract.toLowerCase().includes(q) ||
    p.authors.some(a => a.toLowerCase().includes(q)) ||
    p.venue.toLowerCase().includes(q) ||
    p.category.toLowerCase().includes(q)
  );
}

export function filterPapers(papers: CuratedPaper[], filters: { category?: string; fieldOfStudy?: string; yearRange?: string; sort?: string }): CuratedPaper[] {
  let result = [...papers];
  if (filters.category && filters.category !== "all") {
    result = result.filter(p => p.category === filters.category);
  }
  if (filters.fieldOfStudy && filters.fieldOfStudy !== "All") {
    result = result.filter(p => p.fieldOfStudy === filters.fieldOfStudy);
  }
  if (filters.yearRange && filters.yearRange !== "all") {
    if (filters.yearRange === "2023-2025") result = result.filter(p => p.year >= 2023);
    else if (filters.yearRange === "2020-2022") result = result.filter(p => p.year >= 2020 && p.year <= 2022);
    else if (filters.yearRange === "before-2020") result = result.filter(p => p.year < 2020);
  }
  if (filters.sort === "citations") result.sort((a, b) => b.citations - a.citations);
  else if (filters.sort === "newest") result.sort((a, b) => b.year - a.year);
  else if (filters.sort === "oldest") result.sort((a, b) => a.year - b.year);
  else if (filters.sort === "az") result.sort((a, b) => a.title.localeCompare(b.title));
  return result;
}
